-- Create "route_udp" table
CREATE TABLE "route_udp" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "org_id" character varying NOT NULL, "flow_idle_timeout_seconds" bigint NOT NULL DEFAULT 60, "route_id" character varying NOT NULL, "port_allocation_id" character varying NOT NULL, PRIMARY KEY ("id"), CONSTRAINT "route_udp_port_allocations_port" FOREIGN KEY ("org_id", "port_allocation_id") REFERENCES "port_allocations" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "route_udp_routes_route" FOREIGN KEY ("org_id", "route_id") REFERENCES "routes" ("org_id", "id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "route_udp_orgs" FOREIGN KEY ("org_id") REFERENCES "orgs" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "routeudp_org_id_id" to table: "route_udp"
CREATE UNIQUE INDEX "routeudp_org_id_id" ON "route_udp" ("org_id", "id");
-- Create index "routeudp_port_allocation_id" to table: "route_udp"
CREATE UNIQUE INDEX "routeudp_port_allocation_id" ON "route_udp" ("port_allocation_id");
-- Create index "routeudp_route_id" to table: "route_udp"
CREATE UNIQUE INDEX "routeudp_route_id" ON "route_udp" ("route_id");
